mapper.select:
 /* Risk01Mapper.selectRiskTypeList */
 SELECT
 	A.CMPNY_CD 			AS cmpnyCd
 	, A.RISK_TYPE_CD	AS riskTypeCd
 	, A.RISK_TYPE_NM	AS riskTypeNm
 	, A.SITE_CD			AS siteCd
 	, A.PROCESS_CD		AS processCd
 	, A.USE_YN			AS useYn
 	, A.RISK_TYPE_DESC	AS riskTypeDesc
	FROM TB_RISK_TYPE A
	WHERE 1=1

	  AND A.CMPNY_CD = #{gvCmpnyCd}
	  AND (
	  	A.SITE_CD IS NULL OR A.SITE_CD = ''

	      OR A.SITE_CD = #{siteCd}

	  )

	  	AND A.PROCESS_CD = #{processCd}


	  	AND A.RISK_TYPE_NM LIKE CONCAT('%', #{riskTypeNm}, '%')


	  	AND A.USE_YN = #{useYn}

 /* Risk01Mapper.selectRiskHazardCnt */
 SELECT COUNT(*)
	FROM TB_RISK_SITE_HAZARD
	WHERE 1=1
	  AND CMPNY_CD = #{gvCmpnyCd}
	  AND RISK_TYPE_CD = #{riskTypeCd}

mapper.delete:
/* Risk01Mapper.deleteRistType */
DELETE FROM TB_RISK_TYPE
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND RISK_TYPE_CD = #{riskTypeCd}

  	AND SITE_CD = #{siteCd}

  AND PROCESS_CD = #{processCd}

mapper.select:
/* Risk01Mapper.selectRiskHazardList */ SELECT '' AS chk , CMPNY_CD AS cmpnyCd , RISK_TYPE_CD AS riskTypeCd , HAZARD_CD AS hazardCd , HAZARD_NM AS hazardNm , SITE_CD AS siteCd , HAZARD_DESC AS hazardDesc FROM TB_RISK_SITE_HAZARD WHERE 1=1 AND CMPNY_CD = #{gvCmpnyCd} AND RISK_TYPE_CD = #{riskTypeCd}
AND HAZARD_NM LIKE CONCAT('%', #{hazardNm}, '%')
AND HAZARD_DESC LIKE CONCAT('%', #{hazardDesc}, '%')

mapper.update:
	/* Risk01Mapper.mergeRiskHazard */
	INSERT INTO TB_RISK_SITE_HAZARD (
    	CMPNY_CD
    	, RISK_TYPE_CD
    	, HAZARD_CD
    	, HAZARD_NM
    	, SITE_CD
    	, HAZARD_DESC  	
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{riskTypeCd}
   		, IFNULL(#{hazardCd}, FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'HAZARD_CD'))
   		, #{hazardNm}
   		, NULLIF(#{siteCd}, '')
		, #{hazardDesc}
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now() 
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
	    HAZARD_NM		= NEW.HAZARD_NM
	    , HAZARD_DESC	= NEW.HAZARD_DESC
	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

mapper.delete:
/* Risk01Mapper.deleteRiskHazard */
DELETE FROM TB_RISK_SITE_HAZARD
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND RISK_TYPE_CD = #{riskTypeCd}
  AND HAZARD_CD = #{hazardCd}

  	AND SITE_CD = #{siteCd}
